\set ON_ERROR_STOP 1
begin;
create function pg_temp.document_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FALHA Documentos: %',label;end if;raise notice 'ok Documentos: %',label;end $$;
create function pg_temp.document_denied(command text) returns void language plpgsql as $$begin begin execute command;exception when others then return;end;raise exception 'Deveria negar';end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111111',true);
select set_config('app.catalog_item',create_catalog_item('produto_teste','Produto teste','produto','Descricao',100,40,'Categoria',10)::text,true);
select pg_temp.document_assert((select unit_cost=40 from service_catalog where id=current_setting('app.catalog_item')::uuid),'custo cadastrado real');
insert into lead_proposals(lead_id,title,status,created_by) select id,'Proposta editor teste','rascunho',auth.uid() from leads where cnpj_basico='12ABC345';
select set_config('app.document',(select id::text from lead_proposals where title='Proposta editor teste'),true);
select save_proposal_document(current_setting('app.document')::uuid,'Titulo revisado','Escopo confirmado','2 parcelas','30 dias','Notas',jsonb_build_array(jsonb_build_object('service_id',current_setting('app.catalog_item'),'description','Produto teste','quantity',2,'unit_price',100,'discount_percent',10)),'comercial');
select pg_temp.document_assert((proposal_document(current_setting('app.document')::uuid)#>>'{proposal,amount}')::numeric=180,'total calculado no servidor com desconto');
select approve_proposal_document(current_setting('app.document')::uuid);
select pg_temp.document_assert((select approved_at is not null from lead_proposals where id=current_setting('app.document')::uuid),'aprovacao interna registrada');
select save_proposal_document(current_setting('app.document')::uuid,'Nova revisao','Novo escopo','2 parcelas','30 dias','Notas','[]','comercial');
select pg_temp.document_assert((select approved_at is null from lead_proposals where id=current_setting('app.document')::uuid),'alteracao invalida aprovacao anterior');
update lead_proposals set status='enviada' where id=current_setting('app.document')::uuid;
select pg_temp.document_denied($$select save_proposal_document(current_setting('app.document')::uuid,'x','x','x','x','x','[]','comercial')$$);
select pg_temp.document_denied($$update lead_proposals set scope='bypass' where id=current_setting('app.document')::uuid$$);
select pg_temp.document_denied($$insert into lead_proposals(lead_id,title,created_by,approved_at,approved_by) select lead_id,'Forjado',auth.uid(),now(),auth.uid() from lead_proposals where id=current_setting('app.document')::uuid$$);
select pg_temp.document_assert(duplicate_proposal_document(current_setting('app.document')::uuid) is not null,'copia preserva proposta enviada');
select pg_temp.document_assert(save_proposal_template('Modelo teste','Escopo padrao','2 parcelas','30 dias') is not null,'modelo configuravel');
insert into contracts(lead_id,title,total_value,status) select id,'Contrato satisfacao',100,'ativo' from leads where cnpj_basico='12ABC345';
select pg_temp.document_assert(record_customer_review((select id from contracts where title='Contrato satisfacao'),4,'Satisfacao relatada',current_date+30) is not null,'pos venda com satisfacao real');
select set_config('request.jwt.claim.sub','33333333-3333-3333-3333-333333333333',true);
select pg_temp.document_denied($$select approve_proposal_document(current_setting('app.document')::uuid)$$);
select pg_temp.document_denied($$select create_catalog_item('forjado','Forjado','produto','',0,0,'',0)$$);
reset role;
rollback;
